import AppKit

struct ClipItem: Identifiable, Equatable {
    let id = UUID()
    var text: String
    var date = Date()
}

/// Remembers the last 3 text items you copied. Held in memory only: nothing is written
/// to disk, and items that password managers mark as concealed are never recorded.
@MainActor
final class ClipboardStore: ObservableObject {
    static let limit = 3
    private static let ignoredTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
        "de.petermaurer.TransientPasteboardType",
    ]

    @Published private(set) var items: [ClipItem] = []
    @Published private(set) var copiedID: UUID?

    private var timer: Timer?
    private var lastChange = NSPasteboard.general.changeCount

    func start() {
        guard timer == nil else { return }
        lastChange = NSPasteboard.general.changeCount
        timer = Timer.scheduledTimer(withTimeInterval: 1.0, repeats: true) { [weak self] _ in
            MainActor.assumeIsolated { self?.poll() }
        }
    }

    func stop() {
        timer?.invalidate()
        timer = nil
        items.removeAll() // turning the widget off forgets everything
    }

    private func poll() {
        let pasteboard = NSPasteboard.general
        guard pasteboard.changeCount != lastChange else { return }
        lastChange = pasteboard.changeCount

        let types = Set((pasteboard.types ?? []).map(\.rawValue))
        guard types.isDisjoint(with: Self.ignoredTypes),
              let text = pasteboard.string(forType: .string)?.trimmingCharacters(in: .whitespacesAndNewlines),
              !text.isEmpty
        else { return }
        insert(text)
    }

    private func insert(_ text: String) {
        items.removeAll { $0.text == text }
        items.insert(ClipItem(text: text), at: 0)
        if items.count > Self.limit { items.removeLast(items.count - Self.limit) }
    }

    /// Puts an item back on the clipboard and moves it to the top.
    func copy(_ item: ClipItem) {
        let pasteboard = NSPasteboard.general
        pasteboard.clearContents()
        pasteboard.setString(item.text, forType: .string)
        lastChange = pasteboard.changeCount // our own write isn't a new copy
        items.removeAll { $0.id == item.id }
        let fresh = ClipItem(text: item.text)
        items.insert(fresh, at: 0)
        copiedID = fresh.id
        Task { [weak self] in
            try? await Task.sleep(for: .seconds(1.4))
            if self?.copiedID == fresh.id { self?.copiedID = nil }
        }
    }

    func clear() { items.removeAll() }

    func loadDemo() {
        items = ["swift build -c release", "harsha@example.com", "https://github.com/"]
            .enumerated().map { ClipItem(text: $1, date: Date().addingTimeInterval(-Double($0) * 420)) }
        copiedID = items.first?.id
    }
}
